# Franja horaria
def franja(h):
    if 6 <= h < 12:
        return "Mañana"
    elif 12 <= h < 18:
        return "Tarde"
    elif 18 <= h < 24:
        return "Noche"
    else:
        return "Madrugada"

df["franja"] = df["hour_day"].apply(franja)
